INSERT INTO articulos (
  slug, titulo, extracto, contenido, imagen_destacada, estado, metadata, created_at, updated_at, categoria_id, autor_id
) VALUES (
  'el-lenguaje-de-los-labios', 'El Lenguaje de los Labios', 'Dinámica de atención kinésica y lectura labial donde los scouts descifran mensajes y canciones vocalizando exageradamente sin emitir ningún sonido.', '<h2>📜 Descripción de El Lenguaje de los Labios</h2>
<p><b>El Lenguaje de los Labios</b> es una dinámica scout de lectura facial, atención visual y concentración expresiva. En esta actividad, los participantes se dividen en equipos o parejas. Un integrante debe comunicar oraciones completas, canciones scouts o frases célebres modulando exageradamente los movimientos de la boca y los labios, pero sin emitir absolutamente ningún sonido audible. Sus compañeros deben interpretar la gesticulación y adivinar el mensaje en el menor tiempo posible.</p>
<p>Esta dinámica desarrolla la empatía comunicativa, el enfoque visual y la fluidez expresiva en Manada, Compañía y Tropa.</p>

<h2>🎲 ¿Cómo se juega El Lenguaje de los Labios?</h2>
<p>Para llevar a cabo la dinámica con precisión y entusiasmo, los dirigentes deben seguir estos pasos:</p>
<ul>
  <li><b>Formación de Equipos:</b> Se forman parejas o pequeños grupos frente a frente a dos metros de distancia.</li>
  <li><b>Entrega de la Tarjeta:</b> El dirigente muestra al emisor una tarjeta con una frase scout, el título de una canción tradicional o una instrucción de campamento.</li>
  <li><b>Vocalización Muda:</b> El emisor comienza a ''hablar'' o ''cantar'' marcando de forma acentuada la articulación de cada vocal y consonante sin emitir sonido vocal ni susurros.</li>
  <li><b>Descifrado e Intérprete:</b> Los receptores observan la boca del emisor y anotan o proclaman en voz alta las palabras que logren descifrar.</li>
  <li><b>Puntuación y Relevo:</b> Cada frase descifrada otorga un punto al equipo. Se cambian los roles para que todos ejerciten tanto la emisión como la lectura labial.</li>
</ul>

<h2>🏆 Cómputo de Puntos y Condición de Victoria de El Lenguaje de los Labios</h2>
<p>La actividad premia la claridad gestual y la sintonía de equipo en el Tally:</p>
<ul>
  <li><b>Mayor Cantidad de Frases Descifradas:</b> Otorgar 5 puntos a la patrulla o seisena que adivine la mayor cantidad de mensajes en el tiempo límite.</li>
  <li><b>Mejor Modulación Facial:</b> Otorgar 3 puntos al participante que demuestre la gesticulación labial más limpia e inteligible.</li>
  <li><b>Atención y Enfoque:</b> Otorgar 3 puntos al equipo que mantenga la mejor concentración y escucha visual.</li>
</ul>', '/uploads/el-lenguaje-de-los-labios.webp', 'publicado', '{"areas": ["afectividad", "creatividad", "sociabilidad"], "unidades": ["manada", "compañía", "tropa"], "duracion": "15 minutos", "cantidad": "02 participantes", "lugares": ["Interior", "Exterior"], "materiales": ["Tarjetas con Frases"], "objetivos": ["Practicar una conducta asertiva y una actitud afectuosa", "Expresar pensamientos y emociones por distintos medios", "Estimular la atención visual y gesticulación", "Fomentar la comunicación empática"], "justificacion_areas": "El Lenguaje de los Labios potencia la afectividad al ejercitar la comunicación asertiva, el respeto por los ritmos del otro y la empatía no verbal. Desarrolla la creatividad al requerir la adaptación kinésica e intensificación de la gesticulación facial para transmitir mensajes complejos. Fortalece la sociabilidad al consolidar la atención de grupo y la integración de canales alternativos de diálogo.", "variaciones": "<b>Canto Mudo en Cadena:</b> Un emisor canta una canción scout de forma muda y el grupo debe unirse a cantar en voz alta en el tono correcto una vez descifrada.<br><b>El Mensaje del Silbido mudo:</b> Exigir la transmisión de claves o números utilizando sólo la forma de los labios al pronunciar las vocales.<br><b>Lectura Labial a Distancia:</b> Aumentar la distancia física a 5 metros utilizando pañolines para señalar los límites de cada palabra.", "recomendaciones": "Asegurar que el espacio cuente con buena iluminación frontal para que los receptores puedan distinguir claramente el movimiento labial. Fomentar la paciencia y evitar que los participantes se frustren si no adivinan a la primera. Adaptar el nivel de dificultad de las frases según la unidad.", "objetivos_educativos": [{"id": "ab6e594f-b0a0-4e6d-96aa-7779299b02ef", "area": "Afectividad", "unidad": "Manada", "texto": "Trato con cariño a los demás en la Manada y me gusta que me traten igual.", "como_se_cumple": "Comunicándome con paciencia y afecto hacia mi pareja de juego durante la lectura labial."}, {"id": "c8993915-0234-464c-934e-2a09f8c4338e", "area": "Afectividad", "unidad": "Manada", "texto": "Digo lo que pienso sin ofender o insultar a mis compañeros ni burlarme de ellos.", "como_se_cumple": "Expresando pensamientos de forma asertiva y respetuosa sin caer en burlas ante los errores."}, {"id": "2f8359db-221e-4a64-b2df-2b3e7b74a2db", "area": "Afectividad", "unidad": "Compañía", "texto": "Escucho las opiniones de las demás personas y si no estoy de acuerdo lo digo con respeto.", "como_se_cumple": "Escuchando visualmente al compañero con atención y paciencia sin interrumpir su gesticulación."}, {"id": "672a5da0-8cab-42bb-85dd-0d1f285a1b91", "area": "Afectividad", "unidad": "Compañía", "texto": "Digo lo que pienso con respeto hacia las demás personas.", "como_se_cumple": "Comunicando mensajes e ideas con claridad, asertividad y deferencia hacia el receptor."}, {"id": "a4060c60-7ce9-425b-bf2a-76941a689937", "area": "Afectividad", "unidad": "Tropa", "texto": "Escucho las opiniones de los demás personas y si no estoy de acuerdo lo digo con respeto.", "como_se_cumple": "Desarrollando empatía no verbal para comprender la emisión del compañero de patrulla."}, {"id": "4ade9c82-6b0d-4a44-8bc6-2eb47a011ffb", "area": "Afectividad", "unidad": "Tropa", "texto": "Digo lo que pienso con respeto hacia los demás personas.", "como_se_cumple": "Transmitiendo consignas con convicción, firmeza y absoluto respeto por la integridad del otro."}, {"id": "52b5580a-7d0f-454f-b2ae-0d3318129165", "area": "Creatividad", "unidad": "Manada", "texto": "Canto, bailo y preparo actuaciones con mis amigos de la Manada.", "como_se_cumple": "Gesticulando y representando vocalizaciones de canciones scouts para la seisena."}, {"id": "47e7e2d8-12cd-447d-8df4-251e83aa547b", "area": "Creatividad", "unidad": "Manada", "texto": "Trato de hablar claro y conocer nuevas palabras.", "como_se_cumple": "Acentuando la dicción y la modulación limpia de cada palabra ante el grupo."}, {"id": "d581cfa7-db1f-4b08-b4d3-525b23e418ea", "area": "Creatividad", "unidad": "Compañía", "texto": "Participo con entusiasmo en las actividades artísticas de mi Compañía.", "como_se_cumple": "Participando con soltura y creatividad en la interpretación de mensajes silenciosos."}, {"id": "9758e4f9-728b-4435-a8a3-11fd36c5e3be", "area": "Creatividad", "unidad": "Compañía", "texto": "Expreso por distintos medios mis intereses y aptitudes artísticas.", "como_se_cumple": "Utilizando el canal facial y kinesiológico como medio alternativo de expresión."}, {"id": "39eaf1aa-f703-4fd0-a4b3-b9756dc30539", "area": "Creatividad", "unidad": "Tropa", "texto": "Participo con entusiasmo en las actividades artísticas de mi Tropa.", "como_se_cumple": "Dinamizando el juego con entusiamo y ritmo constante en la patrulla."}, {"id": "6e910d1c-7021-49a5-9ece-637f480a1ec7", "area": "Creatividad", "unidad": "Tropa", "texto": "Expreso por distintos medios mis intereses y aptitudes artísticas.", "como_se_cumple": "Explorando la riqueza expresiva del rostro y los labios en el arte de comunicar."}, {"id": "b69188bf-2391-43c1-a885-abd1b13912be", "area": "Sociabilidad", "unidad": "Manada", "texto": "Acepto las reglas que se ponen en mi casa, en la escuela y en la Manada.", "como_se_cumple": "Respetando con honestidad la prohibición estricta de emitir sonido vocal."}, {"id": "2394dd5b-87b9-4f3d-9cdd-a42649139782", "area": "Sociabilidad", "unidad": "Manada", "texto": "Comprendo y respeto las normas que se han puesto en mi casa y en la escuela, aunque no siempre esté de acuerdo con ellas", "como_se_cumple": "Acatando los tiempos de respuesta y respetando las deducciones de los compañeros."}, {"id": "007e85ea-2b06-48c2-8ac1-873d59643aae", "area": "Sociabilidad", "unidad": "Compañía", "texto": "Conozco y respeto las principales normas de convivencia.", "como_se_cumple": "Promoviendo un ambiente de integración, escucha atenta y juego limpio."}, {"id": "de2f5693-de4b-48f1-b870-3c62be99aea8", "area": "Sociabilidad", "unidad": "Compañía", "texto": "Respeto las normas de convivencia de los distintos ambientes en que actúo, aunque no siempre esté de acuerdo con ellas.", "como_se_cumple": "Manteniendo el comportamiento ético y fraterno en las actividades de equipo."}, {"id": "857f21bc-db3c-4e5e-bcd5-d3d331276fad", "area": "Sociabilidad", "unidad": "Tropa", "texto": "Conozco y respeto las principales normas de convivencia.", "como_se_cumple": "Cumpliendo con lealtad las reglas de articulación silenciosa."}, {"id": "bbc48d53-f4aa-4de7-84d4-95614df76034", "area": "Sociabilidad", "unidad": "Tropa", "texto": "Respeto las normas de convivencia de los distintos ambientes en que actúo, aunque no siempre esté de acuerdo con ellas.", "como_se_cumple": "Favoreciendo la sana convivencia y la cohesión de la Tropa a través del diálogo."}]}'::jsonb, NOW(), NOW(), NULL, NULL
);

